-- Timestamp generated by supabase migration new password_reset_queue.
-- Recovery is handled by the Express authority, never the public Data API.
CREATE TABLE temuevent.password_reset_tokens (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  recipient_email VARCHAR(254) NOT NULL,
  user_id UUID REFERENCES temuevent.users(id) ON DELETE CASCADE ON UPDATE CASCADE,
  token_hash VARCHAR(64) NOT NULL UNIQUE,
  credential_fingerprint VARCHAR(64),
  created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at TIMESTAMPTZ(3) NOT NULL,
  consumed_at TIMESTAMPTZ(3),
  delivery_state VARCHAR(16) NOT NULL DEFAULT 'PENDING',
  attempt_count INTEGER NOT NULL DEFAULT 0,
  lease_id UUID,
  leased_until TIMESTAMPTZ(3),
  next_attempt_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT reset_hash_format CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  CONSTRAINT reset_fingerprint_format CHECK (credential_fingerprint IS NULL OR credential_fingerprint ~ '^[0-9a-f]{64}$'),
  CONSTRAINT reset_activation_pair CHECK ((user_id IS NULL) = (credential_fingerprint IS NULL)),
  CONSTRAINT reset_expiry_order CHECK (expires_at > created_at),
  CONSTRAINT reset_consumption_order CHECK (consumed_at IS NULL OR consumed_at >= created_at),
  CONSTRAINT reset_delivery_state CHECK (delivery_state IN ('PENDING','SENDING','ACCEPTED','SUPPRESSED','RETRY','FAILED')),
  CONSTRAINT reset_attempt_bounds CHECK (attempt_count BETWEEN 0 AND 3),
  CONSTRAINT reset_lease_pair CHECK ((lease_id IS NULL) = (leased_until IS NULL)),
  CONSTRAINT reset_recipient_normalized CHECK (recipient_email = lower(btrim(recipient_email)))
);
CREATE INDEX password_reset_tokens_user_id_idx ON temuevent.password_reset_tokens(user_id);
CREATE INDEX password_reset_tokens_recipient_email_created_at_idx ON temuevent.password_reset_tokens(recipient_email, created_at);
CREATE INDEX password_reset_tokens_created_at_idx ON temuevent.password_reset_tokens(created_at);
CREATE INDEX password_reset_tokens_delivery_state_next_attempt_at_idx ON temuevent.password_reset_tokens(delivery_state, next_attempt_at);
ALTER TABLE temuevent.password_reset_tokens ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON temuevent.password_reset_tokens FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON temuevent.password_reset_tokens TO temuevent_app;
CREATE POLICY password_reset_tokens_backend_access ON temuevent.password_reset_tokens
  FOR ALL TO temuevent_app USING (true) WITH CHECK (true);
